@Component("trainingRun-handler")
@ProcessingGroup("trainingRun-processing-group")
public class TrainingRunEventHandler {
	
	// core constructor
	TrainingRunEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTrainingRunEvent
     */
    @EventHandler
    public void handle( CreateTrainingRunEvent event) {
        entityManager.persist(new TrainingRun(event.getTrainingRunId(), event.getRunLabel(), event.getStartedAt(), event.getCompletedAt(), event.getExperiment(), event.getModelVersion(), event.getInputDatasets(), event.getFeatures(), event.getRunMetrics(), event.getRunParameters(), event.getStatus()));
    }

    /*
     * @param	event UpdateTrainingRunEvent
     */
    @EventHandler
    public TrainingRun handle( UpdateTrainingRunEvent event) {
    	entityManager.merge(new TrainingRun(event.getTrainingRunId(), event.getRunLabel(), event.getStartedAt(), event.getCompletedAt(), event.getExperiment(), event.getModelVersion(), event.getInputDatasets(), event.getFeatures(), event.getRunMetrics(), event.getRunParameters(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteTrainingRunEvent
     */
    @EventHandler
    public void on( DeleteTrainingRunEvent event) {
    	TrainingRun entity = new TrainingRun();
   
    	// ------------------------------------------
    	// apply the TrainingRunId
    	// ------------------------------------------
    	entity.setTrainingRunId( event.getTrainingRunId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TrainingRunRepository trainingRunEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TrainingRunEventHandler.class.getName());

}
